"""Probe driver: python3 run.py <cmds.json> <cwd>  (PYTHONPATH selects the tree). Prints JSON per command:
parse targets, and read_view (if present) text/codes, and _kind of each simple."""
import json, os, sys
sys.setrecursionlimit(5000)
from gov.guard import decide
try:
    from gov.guard import bash_writes as bw
except Exception:
    bw = None
cmds = json.load(open(sys.argv[1]))
cwd = sys.argv[2]
out = []
for c in cmds:
    r = {"cmd": c}
    try:
        r["parse"] = decide._extract_bash_write_targets(c, cwd)
    except Exception as e:
        r["parse"] = "EXC:" + repr(e)
    if bw is not None and hasattr(bw, "read_view"):
        try:
            t, codes = bw.read_view(c)
            r["rv"] = [t, codes]
        except Exception as e:
            r["rv"] = "EXC:" + repr(e)
    out.append(r)
print(json.dumps(out))

"""python3 cmp.py <cmds.json> : runs run.py on base, r1, new; prints a table; flags fail-opens."""
import json, os, subprocess, sys
A2 = os.path.dirname(os.path.abspath(__file__))
cmds = sys.argv[1]
cwd = os.path.join(A2, "case")
for d in ("tests/acceptance/X", "src"):
    os.makedirs(os.path.join(cwd, d), exist_ok=True)
for f, t in (("tests/acceptance/X/t.py", "a='a'\n"), ("x.py", "x=1\n"), ("script.sh", "echo hi\n"), ("run.sh", "echo hi\n")):
    open(os.path.join(cwd, f), "w").write(t)
cwd = os.path.realpath(cwd)
res = {}
for tree in ("base", "r1", "new"):
    env = dict(os.environ, PYTHONPATH=os.path.join(A2, tree, "src"), PYTHONDONTWRITEBYTECODE="1")
    for k in ("GOV_ROLE", "GOV_TICKET", "CLAUDE_PROJECT_DIR", "GOV_HEAVY_SLOT"):
        env.pop(k, None)
    p = subprocess.run([sys.executable, os.path.join(A2, "run.py"), cmds, cwd], env=env, capture_output=True,
                       text=True, cwd=A2)
    if p.returncode:
        print(tree, p.stderr[-2000:]); sys.exit(1)
    res[tree] = json.loads(p.stdout)
U = "/<guard-unresolvable>"


def short(ts):
    if ts is None:
        return "-"
    if isinstance(ts, str):
        return ts
    return ",".join(sorted({"U" if t == U else os.path.relpath(t, cwd) if t.startswith(cwd) else t for t in ts}))


def kept(rv, cmd):
    """Whether read_view keeps the heredoc body lines in text (shell) / codes / cut."""
    if rv is None:
        return "?"
    if isinstance(rv, str):
        return rv
    t, codes = rv
    lines = cmd.split("\n")[1:-1]
    if not lines:
        return "nobody"
    body = lines[-1]
    return "kept" if body in t else ("code" if any(body in c for c in codes) else "CUT")


bad = 0
for i, b in enumerate(res["base"]):
    r1, n = res["r1"][i], res["new"][i]
    c = b["cmd"]
    flag = ""
    if b["parse"] and not n["parse"]:
        flag += " FAILOPEN-vs-base"
    if r1["parse"] and not n["parse"]:
        flag += " FAILOPEN-vs-r1"
    if kept(r1.get("rv"), c) == "kept" and kept(n.get("rv"), c) != "kept":
        flag += " READ-LOST-vs-r1"
    bad += bool(flag)
    print(f"[{i}] {c.splitlines()[0][:70]!r}\n    base={short(b['parse'])} | r1={short(r1['parse'])} | new={short(n['parse'])}"
          f" | rv r1={kept(r1.get('rv'), c)} new={kept(n.get('rv'), c)}{flag}")
print("flagged:", bad)
